export type CloseAction = "tray" | "quit";

export type UiTarget = "main" | "tray_panel" | "overlay";

export type OsdStyle = "vertical" | "horizontal";

export type OsdLook = "classic" | "sketch";

export type OsdEdge = "left" | "right" | "top" | "bottom";

export type OsdPrefs = { look: OsdLook, primary_monitor: boolean, style: OsdStyle,
/**
 * `left`/`right` for `vertical`, `top`/`bottom` for `horizontal`.
 */
edge: OsdEdge,
/**
 * Percent of the screen from the edge toward the center, 0…`OSD_MAX_OFFSET_PCT`.
 */
offset_pct: number, };

export type OverlayPrefs = {
/**
 * Off: the overlay hotkey and the tray do not open it.
 */
enabled: boolean,
/**
 * The order the overlay lays its parts out in (the layout editor in Settings); parts
 * missing here follow in the default order.
 */
order: Array<OverlayItem>, volumes: boolean, mic_switch: boolean, processing_switch: boolean, mixer_switch: boolean, dictation_history: boolean,
/**
 * The display profiles list (§8.5), where `Capabilities::displays` is set.
 */
display_profiles: boolean, preset: boolean, output_device: boolean, mic_level: boolean, expand: OverlayExpand, placement: OverlayPlacement, };

export type OverlayExpand = "right" | "left" | "down";

export type OverlayItem = "volumes" | "mic_switch" | "processing_switch" | "mixer_switch" | "dictation" | "dictation_history" | "sounds" | "display_profiles" | "output_device" | "mic_level" | "preset";

export type OverlayPlacement = "anchored" | "centered";

export type Preferences = { volume_step_pct: number,
/**
 * Preferred PipeWire quantum for Macafon's nodes; other apps may make it smaller.
 */
quantum_frames: number, close_action: CloseAction,
/**
 * The hotkey popup; applies where `Capabilities::hotkey_popup` is set.
 */
osd: OsdPrefs, overlay: OverlayPrefs,
/**
 * The monitor the main window opens on (its system name); empty: where the system puts it.
 */
main_monitor: string, };

export type SoundInfo = {
/**
 * Path inside the library folder with `/` separators, `Memes/airhorn.mp3`; stable key for
 * hotkeys (`soundpad_play.<id>`) and per-sound settings.
 */
id: string,
/**
 * File name without extension.
 */
name: string,
/**
 * First-level subfolder; `null` for files in the folder itself.
 */
category: string | null,
/**
 * Known once the file was probed or decoded.
 */
duration_ms: number | null,
/**
 * Per-sound volume, 0…200 %.
 */
volume_pct: number, favorite: boolean,
/**
 * Times played, for sorting like Soundpad's play count.
 */
play_count: number,
/**
 * When the file came into the library (its creation time), Unix ms; newest first is the
 * default order.
 */
added_unix_ms: number,
/**
 * The file could not be decoded.
 */
error: string | null, };

export type SoundpadPlayback = { sound_id: string, position_ms: number, duration_ms: number, paused: boolean, looping: boolean,
/**
 * Decoding: playback starts as soon as the sound is ready.
 */
loading: boolean, };

export type SoundpadOverlayView = "grid" | "list";

export type SoundpadOverlayControls = "top" | "bottom" | "hidden";

export type SoundpadPrefs = {
/**
 * Play into Macafon Microphone, heard by the voice chat.
 */
to_microphone: boolean,
/**
 * Play into the monitor device too, so the user hears the sound.
 */
to_headphones: boolean,
/**
 * 0…200 %.
 */
microphone_volume_pct: number,
/**
 * 0…200 %.
 */
headphones_volume_pct: number,
/**
 * Silence the voice while a sound plays into the microphone.
 */
mute_voice_while_playing: boolean,
/**
 * Monitor output device; `null` follows the system default output.
 */
monitor_device: string | null,
/**
 * Show the soundpad panel in the hotkey overlay.
 */
show_in_overlay: boolean, overlay_view: SoundpadOverlayView, overlay_controls: SoundpadOverlayControls, };

export type SoundpadState = {
/**
 * Absolute path of the library folder.
 */
folder: string,
/**
 * The folder is the default one (`Music\Macafon Sounds`), not picked by the user.
 */
default_folder: boolean,
/**
 * Every first-level subfolder, including empty ones.
 */
categories: Array<string>, sounds: Array<SoundInfo>, problem_sounds: Array<SoundInfo>, prefs: SoundpadPrefs, playback: SoundpadPlayback | null,
/**
 * Sounds reach Macafon Microphone (on Windows: VB-CABLE is installed).
 */
microphone_ready: boolean, };

export type SoundpadPrefsPatch = { to_microphone?: boolean | null, to_headphones?: boolean | null, microphone_volume_pct?: number | null, headphones_volume_pct?: number | null, mute_voice_while_playing?: boolean | null, show_in_overlay?: boolean | null, overlay_view?: SoundpadOverlayView | null, overlay_controls?: SoundpadOverlayControls | null, };

export type SoundPatch = { volume_pct?: number | null, favorite?: boolean | null, };

export type DictationEngine = "whisper" | "parakeet";

export type DictationLanguage = string;

export type DictationLanguageInfo = { code: string, name: string, };

export type DictationLanguagePolicy = "layout" | "fixed" | "auto";

export type DictationTap = "raw" | "clean" | "processed";

export type DictationInsert = "paste" | "type";

export type DictationGamePolicy = "insert" | "copy" | "ignore";

export type DictationPopupLook = "flow" | "analog";

export type DictationPopupPosition = "bottom" | "top";

export type DictationPrefs = {
/**
 * STT-001: off by default; off costs nothing.
 */
enabled: boolean, engine: DictationEngine,
/**
 * Manifest id of the chosen model of `engine`; `null` until one is downloaded.
 */
model: string | null, language: DictationLanguagePolicy, fixed_language: DictationLanguage, tap: DictationTap,
/**
 * STT-006.
 */
mute_mic_while_dictating: boolean, insert: DictationInsert, trailing_space: boolean, fullscreen_games: DictationGamePolicy,
/**
 * STT-007: seconds after the last use; 0 = immediately, -1 = never.
 */
unload_after_s: number,
/**
 * STT-008: inference threads; 0 = max(2, physical cores / 2).
 */
threads: number, game_mode: boolean,
/**
 * STT-020: Whisper runs on the GPU (Vulkan) when one is available; Parakeet stays on the
 * CPU. A failed GPU load falls back to the CPU.
 */
gpu: boolean,
/**
 * STT-005.
 */
pre_roll: boolean,
/**
 * STT-015.
 */
keep_history: boolean,
/**
 * STT-015: keep the history across restarts in a file of the user's profile; off keeps it
 * in memory until Macafon quits (owner request, 2026-10-19).
 */
save_history: boolean,
/**
 * STT-014: Whisper only.
 */
vocabulary: Array<string>, popup_look: DictationPopupLook, popup_position: DictationPopupPosition,
/**
 * Toward the center, percent of the monitor height (`OSD_MAX_OFFSET_PCT` bound).
 */
popup_offset_pct: number,
/**
 * The popup stays on the primary monitor instead of following the active window's one;
 * independent of the hotkey popup's setting.
 */
popup_primary_monitor: boolean,
/**
 * §9.9.2: the Dictation tile in the tray panel and the hotkey overlay.
 */
show_in_overlay: boolean, };

export type DictationPrefsPatch = { enabled?: boolean | null, engine?: DictationEngine | null, model?: string | null, language?: DictationLanguagePolicy | null, fixed_language?: DictationLanguage | null, tap?: DictationTap | null, mute_mic_while_dictating?: boolean | null, insert?: DictationInsert | null, trailing_space?: boolean | null, fullscreen_games?: DictationGamePolicy | null, unload_after_s?: number | null, threads?: number | null, game_mode?: boolean | null, gpu?: boolean | null, pre_roll?: boolean | null, keep_history?: boolean | null, save_history?: boolean | null, vocabulary?: Array<string> | null, popup_look?: DictationPopupLook | null, popup_position?: DictationPopupPosition | null, popup_offset_pct?: number | null, popup_primary_monitor?: boolean | null, show_in_overlay?: boolean | null, };

export type DictationPhase = "off" | "unloaded" | "loading" | "ready" | "listening" | "transcribing" | "error";

export type DictationModelStatus = "missing" | "downloading" | "ready" | "error";

export type DictationModel = {
/**
 * `whisper-large-v3-turbo-q5_0`, `whisper-small-q5_1`, `parakeet-tdt-0.6b-v3-int8`.
 */
id: string, engine: DictationEngine,
/**
 * Short UI name: `Turbo`, `Small`, `Parakeet v3`.
 */
name: string,
/**
 * Total download, VAD included.
 */
size_bytes: number,
/**
 * Static manifest ratings 1…5 for the two meters of card 01.
 */
quality: number, speed: number,
/**
 * The model the UI recommends on an empty state.
 */
recommended: boolean, status: DictationModelStatus,
/**
 * While downloading.
 */
downloaded_bytes: number, bytes_per_sec: number | null, error: string | null, };

export type DictationMove = { to: string, done_bytes: number, total_bytes: number, };

export type DictationStorage = {
/**
 * Absolute path.
 */
folder: string,
/**
 * `%LOCALAPPDATA%\Macafon\models\stt`, not picked by the user.
 */
default_folder: boolean, free_bytes: number | null,
/**
 * Bytes of downloaded models in the folder.
 */
used_bytes: number,
/**
 * The folder is on a spinning disk: cold starts are slower.
 */
rotational: boolean, moving: DictationMove | null, };

export type DictationOutcome = "inserted" | "copied" | "test";

export type DictationResult = { id: number, text: string,
/**
 * `null` when the engine chose it itself (Parakeet).
 */
language: DictationLanguage | null, engine: DictationEngine, model: string,
/**
 * Recorded audio.
 */
audio_ms: number,
/**
 * Key release → text ready.
 */
elapsed_ms: number, at_unix_ms: number, outcome: DictationOutcome, };

export type DictationState = { prefs: DictationPrefs, layout_languages: Array<DictationLanguageInfo>, supported_languages: Array<DictationLanguageInfo>, phase: DictationPhase,
/**
 * Short reason while `phase` is `error`.
 */
error: string | null,
/**
 * The model the worker holds now.
 */
loaded_model: string | null,
/**
 * Worker memory while it runs.
 */
worker_ram_bytes: number | null,
/**
 * Threads the worker uses now.
 */
worker_threads: number | null,
/**
 * The thread count `threads = 0` resolves to, and the slider's upper bound.
 */
default_threads: number, logical_cores: number, models: Array<DictationModel>, storage: DictationStorage,
/**
 * Newest first; empty when `keep_history` is off.
 */
history: Array<DictationResult>, };

export type DictationLevel = { rms_dbfs: number, peak_dbfs: number, };
